import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('rejects weather input without location (spec: specs/hal-engine-tool-input-validation/spec.md#2)', async () => {
    const registry = new ToolRegistry();
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather',
        description: 'Weather by location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => {
        inputs.push(input);
        return JSON.stringify(input);
      }
    );

    const response = await registry.execute('weather', {});

    expect(response.result).toMatch(/required.*location|location.*required/i);
    expect(inputs).toEqual([]);
  });
});
EOF
